import { Controller, Get, Patch, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const PAYROLL_ROLE = '급여 담당자';

function notFound(): ApiError {
  return new ApiError(404, 'DAILY_PAYROLL_NOT_FOUND', '지급 내역을 찾을 수 없습니다.');
}

function invalidInput(): ApiError {
  return new ApiError(422, 'DAILY_PAYROLL_INVALID_INPUT', '필수 항목이 누락되었거나 형식이 올바르지 않습니다.');
}

function idOf(value: unknown): string {
  const text = typeof value === 'string' ? value : '';
  if (!/^\d+$/.test(text)) {
    throw notFound();
  }
  return text;
}

// 값이 있으면 0 이상의 숫자(정수 여부 지정)인지 검사하고, 없으면 null을 돌려준다
function optionalNumber(value: unknown, integer: boolean): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value === 'string' && value.trim() === '') {
    throw invalidInput();
  }
  if (typeof value !== 'number' && typeof value !== 'string') {
    throw invalidInput();
  }
  const num = Number(value);
  if (!Number.isFinite(num) || num < 0) {
    throw invalidInput();
  }
  if (integer && !Number.isInteger(num)) {
    throw invalidInput();
  }
  return String(num);
}

@Controller('api/v1')
export class FnSfr02305Controller {
  @Get('/daily-payrolls/:dailyPayrollId')
  async getDailyPayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require(PAYROLL_ROLE);
    const id = idOf(req.params['dailyPayrollId']);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT p.daily_payroll_id AS "dailyPayrollId",
                w.worker_name AS "workerName",
                w.resident_no_enc AS "residentNoEnc",
                p.pay_date AS "payDate",
                p.work_days AS "workDays",
                p.pay_amount AS "payAmount",
                p.withholding_tax AS "withholdingTax",
                p.closing_status AS "closingStatus"
           FROM daily_payroll p
           JOIN daily_worker w ON w.daily_worker_id = p.daily_worker_id
          WHERE p.daily_payroll_id = CAST(:id AS bigint)`,
        { id },
      );
      if (rows.length === 0) {
        throw notFound();
      }
      return rows[0];
    });
  }

  @Patch('/daily-payrolls/:dailyPayrollId')
  async updateDailyPayroll2(@Req() req: Request) {
    const user = currentUser(req);
    user.require(PAYROLL_ROLE);
    const id = idOf(req.params['dailyPayrollId']);
    const data = checks.inputOf(req.body);
    const workDays = optionalNumber(data['workDays'], true);
    const payAmount = optionalNumber(data['payAmount'], false);
    const withholdingTax = optionalNumber(data['withholdingTax'], false);
    if (workDays === null && payAmount === null && withholdingTax === null) {
      throw invalidInput();
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM daily_payroll
          WHERE daily_payroll_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw notFound();
      }
      if (rows[0]['closingStatus'] === '마감') {
        throw new ApiError(409, 'DAILY_PAYROLL_ALREADY_CLOSED', '확정된 명세서는 수정할 수 없습니다. 확정 취소 절차가 필요합니다.');
      }
      const updated = await db.query(
        `UPDATE daily_payroll
            SET work_days = COALESCE(CAST(:workDays AS integer), work_days),
                pay_amount = COALESCE(CAST(:payAmount AS numeric), pay_amount),
                withholding_tax = COALESCE(CAST(:withholdingTax AS numeric), withholding_tax),
                updated_at = now()
          WHERE daily_payroll_id = CAST(:id AS bigint)
      RETURNING daily_payroll_id AS "dailyPayrollId"`,
        { id, workDays, payAmount, withholdingTax },
      );
      return updated[0];
    });
  }

  @Post('/daily-payrolls/:dailyPayrollId/close')
  @HttpCode(200)
  async closeDailyPayroll(@Req() req: Request) {
    const user = currentUser(req);
    user.require(PAYROLL_ROLE);
    const id = idOf(req.params['dailyPayrollId']);
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT closing_status AS "closingStatus"
           FROM daily_payroll
          WHERE daily_payroll_id = CAST(:id AS bigint)
          FOR UPDATE`,
        { id },
      );
      if (rows.length === 0) {
        throw notFound();
      }
      if (rows[0]['closingStatus'] === '마감') {
        throw new ApiError(409, 'DAILY_PAYROLL_ALREADY_CLOSED', '이미 확정된 명세서입니다.');
      }
      // closed_at 현재 시각: 가정
      const updated = await db.query(
        `UPDATE daily_payroll
            SET closing_status = '마감',
                closed_at = now(),
                updated_at = now()
          WHERE daily_payroll_id = CAST(:id AS bigint)
      RETURNING daily_payroll_id AS "dailyPayrollId",
                closing_status AS "closingStatus",
                closed_at AS "closedAt"`,
        { id },
      );
      return updated[0];
    });
  }
}

