import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateInput,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  Pairs,
  RefName,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

const PAGE_SIZE = 20;

function isBlank(value: unknown): boolean {
  return value === '' || value === undefined || value === null;
}

function CreateDrawer({ role, notify, onClose, onDone }: { role: string; notify: (text: string) => void; onClose: () => void; onDone: () => void }) {
  const [workerId, setWorkerId] = useState<number | string>('');
  const [payDate, setPayDate] = useState('');
  const [workDays, setWorkDays] = useState<number | string>('');
  const [payAmount, setPayAmount] = useState<number | string>('');
  const [tax, setTax] = useState<number | string>('');
  return (
    <Drawer title="지급 내역 등록" onClose={onClose}>
      <Form
        submit="등록"
        onSubmit={async () => {
          if (isBlank(workerId) || isBlank(payDate) || isBlank(workDays) || isBlank(payAmount)) {
            throw new Error('일용직 사원, 급여 지급일, 근무일수, 지급 금액을 입력하세요.');
          }
          const body: Row = { dailyWorkerId: workerId, payDate, workDays, payAmount };
          if (!isBlank(tax)) {
            body.withholdingTax = tax;
          }
          await call('POST', '/daily-payrolls', role, body);
          notify('지급 내역을 등록했습니다.');
          onDone();
          onClose();
        }}
      >
        <Field label="일용직 사원" required>
          <LookupSelect table="daily_worker" role={role} value={workerId} onChange={setWorkerId} />
        </Field>
        <Field label="급여 지급일" required>
          <DateInput value={payDate} onChange={setPayDate} />
        </Field>
        <Field label="근무일수" required>
          <NumberInput value={workDays} onChange={setWorkDays} />
        </Field>
        <Field label="지급 금액" required>
          <NumberInput value={payAmount} onChange={setPayAmount} />
        </Field>
        <Field label="원천징수세액">
          <NumberInput value={tax} onChange={setTax} />
        </Field>
      </Form>
    </Drawer>
  );
}

function DetailDrawer({ id, role, notify, onClose, onChanged }: { id: string; role: string; notify: (text: string) => void; onClose: () => void; onChanged: () => void }) {
  const detail = useData<Row>(() => call<Row>('GET', '/daily-payrolls/' + id, role), [id, role]);
  const [mode, setMode] = useState<'view' | 'edit' | 'close'>('view');
  const [workDays, setWorkDays] = useState<number | string>('');
  const [payAmount, setPayAmount] = useState<number | string>('');
  const [tax, setTax] = useState<number | string>('');
  const row = detail.data;
  const closed = row ? row.closingStatus === '마감' : true;
  return (
    <Drawer title="원천징수영수증" onClose={onClose}>
      {detail.error ? <p>{detail.error}</p> : null}
      {row ? (
        <Pairs
          items={[
            ['성명', String(row.workerName ?? '')],
            ['급여 지급일', <DateText value={row.payDate} />],
            ['근무일수', <Num value={row.workDays} />],
            ['지급 금액', <Num value={row.payAmount} />],
            ['원천징수세액', <Num value={row.withholdingTax} />],
            ['마감 상태', <Badge value={row.closingStatus} />],
          ]}
        />
      ) : null}
      {row && !closed && mode === 'view' ? (
        <Band>
          <button type="button" onClick={() => setMode('edit')}>수정</button>
          <button type="button" onClick={() => setMode('close')}>확정</button>
        </Band>
      ) : null}
      {row && !closed && mode === 'edit' ? (
        <Form
          submit="저장"
          onSubmit={async () => {
            const body: Row = {};
            if (!isBlank(workDays)) {
              body.workDays = workDays;
            }
            if (!isBlank(payAmount)) {
              body.payAmount = payAmount;
            }
            if (!isBlank(tax)) {
              body.withholdingTax = tax;
            }
            if (Object.keys(body).length === 0) {
              throw new Error('수정할 값을 입력하세요.');
            }
            await call('PATCH', '/daily-payrolls/' + id, role, body);
            notify('지급 내역을 수정했습니다.');
            setMode('view');
            detail.reload();
            onChanged();
          }}
        >
          <Field label="근무일수">
            <NumberInput value={workDays} onChange={setWorkDays} />
          </Field>
          <Field label="지급 금액">
            <NumberInput value={payAmount} onChange={setPayAmount} />
          </Field>
          <Field label="원천징수세액">
            <NumberInput value={tax} onChange={setTax} />
          </Field>
        </Form>
      ) : null}
      {row && !closed && mode === 'close' ? (
        <Form
          submit="확정"
          danger
          note="확정하면 확정 취소 절차 없이 수정할 수 없습니다."
          onSubmit={async () => {
            await call('POST', '/daily-payrolls/' + id + '/close', role, {});
            notify('지급명세서를 확정했습니다.');
            setMode('view');
            detail.reload();
            onChanged();
          }}
        />
      ) : null}
    </Drawer>
  );
}

export default function FnSfr02305Page({ role, notify }: PageProps) {
  const [workerId, setWorkerId] = useState<number | string>('');
  const [payDate, setPayDate] = useState('');
  const [query, setQuery] = useState<Row>({});
  const [page, setPage] = useState(0);
  const [detailId, setDetailId] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const list = useData<Page>(
    () => call<Page>('GET', '/daily-payrolls', role, undefined, { ...query, page, size: PAGE_SIZE }),
    [query, page, role],
  );
  const rows = list.data ? list.data.items : [];
  const total = list.data ? list.data.total : 0;
  const pending = rows.filter((r) => r.closingStatus !== '마감');
  const closedCount = rows.length - pending.length;
  return (
    <div className="bento">
      <section className="box span-12">
        <h2>지급명세서 현황</h2>
        <Tiles
          items={[
            ['전체 건수', <Num value={total} />],
            ['처리 대기 (현재 쪽)', <Num value={pending.length} />],
            ['확정 (현재 쪽)', <Num value={closedCount} />],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>지급 내역</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            setQuery({ dailyWorkerId: workerId, payDate });
          }}
          onReset={() => {
            setWorkerId('');
            setPayDate('');
            setPage(0);
            setQuery({});
          }}
        >
          <Field label="일용직 사원">
            <LookupSelect table="daily_worker" role={role} value={workerId} onChange={setWorkerId} />
          </Field>
          <Field label="급여 지급일">
            <DateInput value={payDate} onChange={setPayDate} />
          </Field>
        </Filters>
        <Band total={total}>
          <button type="button" onClick={() => setCreating(true)}>지급 내역 등록</button>
        </Band>
        {list.error ? <p>{list.error}</p> : null}
        <DataTable
          rows={rows}
          empty="지급 내역이 없습니다."
          onRowClick={(r) => setDetailId(String(r.dailyPayrollId))}
          columns={[
            { key: 'dailyWorkerId', label: '일용직 사원', render: (r) => <RefName table="daily_worker" role={role} value={r.dailyWorkerId} /> },
            { key: 'payDate', label: '급여 지급일', render: (r) => <DateText value={r.payDate} /> },
            { key: 'workDays', label: '근무일수', render: (r) => <Num value={r.workDays} /> },
            { key: 'payAmount', label: '지급 금액', render: (r) => <Num value={r.payAmount} /> },
            { key: 'withholdingTax', label: '원천징수세액', render: (r) => <Num value={r.withholdingTax} /> },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r.closingStatus} /> },
          ]}
        />
        <Pager page={page} size={PAGE_SIZE} total={total} onPage={setPage} />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          rows={pending}
          empty="확정할 내역이 없습니다."
          onRowClick={(r) => setDetailId(String(r.dailyPayrollId))}
          columns={[
            { key: 'dailyWorkerId', label: '일용직 사원', render: (r) => <RefName table="daily_worker" role={role} value={r.dailyWorkerId} /> },
            { key: 'payDate', label: '급여 지급일', render: (r) => <DateText value={r.payDate} /> },
            { key: 'closingStatus', label: '마감 상태', render: (r) => <Badge value={r.closingStatus} /> },
          ]}
        />
      </section>
      {creating ? (
        <CreateDrawer role={role} notify={notify} onClose={() => setCreating(false)} onDone={() => list.reload()} />
      ) : null}
      {detailId ? (
        <DetailDrawer id={detailId} role={role} notify={notify} onClose={() => setDetailId(null)} onChanged={() => list.reload()} />
      ) : null}
    </div>
  );
}
